// Core tests: the 9 literal core cases from the fixed spec's fixtures.json
// (vendored verbatim at test/fixtures.json from spec candidate
// 6493df72ecb2c7a583d836fdcb9731b550168b40; expected values taken verbatim,
// never generated by the product), plus hand-derived boundary, rounding,
// and validation-order cases. The SPEC's own rules are the oracle; every
// extra expected value below was computed by hand from those rules.

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/protein.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("every fixture success keeps low <= daily <= high and meals sum to daily", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const { result } = entry.expected;
    assert.ok(result.lowGrams <= result.dailyGrams, entry.id);
    assert.ok(result.dailyGrams <= result.highGrams, entry.id);
    assert.equal(result.perMealGrams.length, result.meals, entry.id);
    assert.equal(
      result.perMealGrams.reduce((sum, grams) => sum + grams, 0),
      result.dailyGrams,
      entry.id,
    );
  }
});

// Hand-derived maximum edges: weight 300.0 with the maximum custom
// factor 4.0. W10=3000, F10=40: daily = (3000*40+50)/100 -> 1200;
// low at 3.8 -> 1140; high at 4.2 -> 1260; four meals of 300.
test("hand-derived maximum weight and maximum custom factor", () => {
  assert.deepEqual(
    run({ weight: "300", goal: "custom", customFactor: "4.0", meals: "4" }),
    {
      ok: true,
      result: {
        factor: "4.0",
        dailyGrams: 1200,
        lowGrams: 1140,
        highGrams: 1260,
        meals: 4,
        perMealGrams: [300, 300, 300, 300],
      },
    },
  );
});

// Hand-derived: custom factor 0.1 clamps the low factor to 0, so the
// range starts at 0 g. W10=1000, F10=1: daily = (1000+50)/100 -> 10;
// high at 0.3 -> 30; three meals split 10 as 4/3/3.
test("hand-derived custom factor 0.1 clamps the range low to zero", () => {
  assert.deepEqual(
    run({ weight: "100", goal: "custom", customFactor: "0.1", meals: "3" }),
    {
      ok: true,
      result: {
        factor: "0.1",
        dailyGrams: 10,
        lowGrams: 0,
        highGrams: 30,
        meals: 3,
        perMealGrams: [4, 3, 3],
      },
    },
  );
});

// Hand-derived: a custom factor typed without a decimal point is
// normalized to exactly one decimal place ("2" -> "2.0"). W10=500,
// F10=20: daily = (10000+50)/100 -> 100; low at 1.8 -> 90; high at
// 2.2 -> 110; three meals split 100 as 34/33/33.
test("hand-derived custom factor normalization to one decimal", () => {
  assert.deepEqual(
    run({ weight: "50", goal: "custom", customFactor: "2", meals: "3" }),
    {
      ok: true,
      result: {
        factor: "2.0",
        dailyGrams: 100,
        lowGrams: 90,
        highGrams: 110,
        meals: 3,
        perMealGrams: [34, 33, 33],
      },
    },
  );
});

// Hand-derived: with a non-custom goal the customFactor value is never
// validated and never participates — even a value that would fail every
// per-field check (too long, non-numeric) is ignored. 70 kg at 1.0:
// daily 70, low at 0.8 -> 56, high at 1.2 -> 84, split 24/23/23.
test("non-custom goals ignore the customFactor value completely", () => {
  assert.deepEqual(
    run({ weight: "70", goal: "general", customFactor: "not a number!!", meals: "3" }),
    {
      ok: true,
      result: {
        factor: "1.0",
        dailyGrams: 70,
        lowGrams: 56,
        highGrams: 84,
        meals: 3,
        perMealGrams: [24, 23, 23],
      },
    },
  );
});

// Hand-derived: the longest goal code (16 units) must not trip the
// 8-unit raw capacity, which the SPEC pins only for weight/customFactor.
// 60 kg at 1.2: daily = (7200+50)/100 -> 72; low at 1.0 -> 60; high at
// 1.4 -> 84; split 24/24/24.
test("the regular-exercise code exceeds 8 units and still validates", () => {
  assert.deepEqual(
    run({ weight: "60", goal: "regular-exercise", customFactor: "", meals: "3" }),
    {
      ok: true,
      result: {
        factor: "1.2",
        dailyGrams: 72,
        lowGrams: 60,
        highGrams: 84,
        meals: 3,
        perMealGrams: [24, 24, 24],
      },
    },
  );
});

// Hand-derived maximum weight with a table factor. 300 kg at 1.0:
// daily 300, low at 0.8 -> 240, high at 1.2 -> 360, split 100/100/100.
test("hand-derived maximum weight boundary is valid", () => {
  assert.deepEqual(
    run({ weight: "300.0", goal: "general", customFactor: "", meals: "3" }),
    {
      ok: true,
      result: {
        factor: "1.0",
        dailyGrams: 300,
        lowGrams: 240,
        highGrams: 360,
        meals: 3,
        perMealGrams: [100, 100, 100],
      },
    },
  );
});

const valid = { weight: "70", goal: "general", customFactor: "", meals: "3" };
const errorOf = (input) => run(input).error;

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("70"), schema);
  assert.deepEqual(errorOf(["70", "general", "", "3"]), schema);
  assert.deepEqual(errorOf({ weight: "70", goal: "general", meals: "3" }), schema);
  assert.deepEqual(errorOf({ ...valid, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...valid, weight: 70 }), schema);
  assert.deepEqual(errorOf({ ...valid, goal: null }), schema);
  const withAccessor = { weight: "70", goal: "general", meals: "3" };
  Object.defineProperty(withAccessor, "customFactor", {
    enumerable: true,
    get() {
      return "";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("validation order: weight, then goal, then customFactor, then meals", () => {
  assert.deepEqual(errorOf({ weight: "300.1", goal: "bogus", customFactor: "", meals: "5" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "bogus", customFactor: "", meals: "5" }), {
    code: "ENUM",
    field: "goal",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "custom", customFactor: "", meals: "5" }), {
    code: "EMPTY",
    field: "customFactor",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "general", customFactor: "", meals: "5" }), {
    code: "ENUM",
    field: "meals",
    row: null,
  });
});

test("per-field order: capacity before unicode before empty before grammar", () => {
  assert.deepEqual(errorOf({ ...valid, weight: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, weight: "12345678\uD800" }), {
    code: "INPUT_LIMIT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, weight: "1\uD800" }), {
    code: "UNICODE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, weight: "" }), {
    code: "EMPTY",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, goal: "" }), {
    code: "EMPTY",
    field: "goal",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, goal: "athlete" }), {
    code: "ENUM",
    field: "goal",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, meals: "" }), {
    code: "EMPTY",
    field: "meals",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "custom", customFactor: "123456789", meals: "3" }), {
    code: "INPUT_LIMIT",
    field: "customFactor",
    row: null,
  });
});

test("decimal grammar rejects signs, spaces, leading zeros, stray dots", () => {
  for (const bad of ["070", "70.", ".5", " 70", "70 ", "+70", "-70", "7,0", "1e2", "70.55"]) {
    assert.deepEqual(
      errorOf({ ...valid, weight: bad }),
      { code: "DECIMAL_FORMAT", field: "weight", row: null },
      `weight ${JSON.stringify(bad)}`,
    );
  }
});

test("range edges just outside each bound", () => {
  assert.deepEqual(errorOf({ ...valid, weight: "19.9" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, weight: "0" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "custom", customFactor: "4.1", meals: "3" }), {
    code: "RANGE",
    field: "customFactor",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "custom", customFactor: "0.0", meals: "3" }), {
    code: "RANGE",
    field: "customFactor",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "70", goal: "custom", customFactor: "x", meals: "3" }), {
    code: "DECIMAL_FORMAT",
    field: "customFactor",
    row: null,
  });
});
